Json: TypeAlias = str | int | float | bool | None | list["Json"] | dict[str, "Json"]
Vec: TypeAlias = tuple[float, float, float]
ROOT = Path(__file__).resolve().parents[2]
ASSETS = ROOT / "src/main/resources/assets/rangedweaponsmod"
CREDIT = (
    "Rusty Shackleford and nfx; original art generated by devtools/art/launcher_art.py"
)
CELLS = {
    "metal_mid": (0, 0),
    "metal_dark": (1, 0),
    "metal_light": (2, 0),
    "barrel": (3, 0),
    "wood": (0, 1),
    "wood_dark": (1, 1),
    "brass": (2, 1),
    "vent": (3, 1),
    "receiver": (0, 2),
    "grip": (1, 2),
    "magazine": (2, 2),
    "muzzle": (3, 2),
}
DIRECTIONS = ("north", "south", "east", "west", "up", "down")


def _box(
    name: str, lo: Vec, hi: Vec, material: str, top: str | None = None
) -> dict[str, Json]:
    faces: dict[str, Json] = {}
    for face in DIRECTIONS:
        cell = top if top and face == "up" else material
        x, y = CELLS[cell]
        faces[face] = {"texture": "#gun", "uv": [x * 4, y * 4, x * 4 + 4, y * 4 + 4]}
    return {"name": name, "from": list(lo), "to": list(hi), "faces": faces}


def _model(elements: list[dict[str, Json]]) -> dict[str, Json]:
    return {
        "credit": CREDIT,
        "texture_size": [32, 32],
        "textures": {
            "gun": "rangedweaponsmod:item/gun_atlas",
            "particle": "rangedweaponsmod:item/gun_atlas",
        },
        "elements": list(elements),
    }


def _launcher() -> dict[str, Json]:
    b = _box
    pieces = [
        b("tube_main", (-10, 9, 5.5), (27, 13, 10.5), "metal_mid"),
        b("tube_top_plane", (-10, 13, 6), (27, 13.5, 10), "metal_mid", "metal_light"),
        b("tube_bottom_plane", (-10, 8.5, 6), (27, 9, 10), "metal_dark"),
        b("wood_shoulder_rest", (-8, 6.5, 6), (-1, 8.5, 10), "wood_dark", "wood"),
        b("shoulder_pad", (-9, 6, 5.8), (-7.5, 8.8, 10.2), "grip"),
        b("lower_receiver", (0, 7, 6.6), (9, 8.5, 9.4), "receiver", "metal_mid"),
        b("grip", (1, 2, 7), (3.5, 7, 9), "grip", "wood"),
        b("grip_heel", (0.8, 1.5, 6.8), (3.7, 2.3, 9.2), "wood_dark"),
        b("trigger_guard_bottom", (3.5, 4.8, 7.5), (7, 5.4, 8.5), "metal_dark"),
        b("trigger_guard_front", (6.4, 4.8, 7.5), (7, 7, 8.5), "metal_dark"),
        b("trigger", (4.3, 5.4, 7.7), (4.9, 7, 8.3), "brass"),
        b("foregrip_mount", (12, 7.3, 6.5), (18, 8.5, 9.5), "metal_dark"),
        b("wood_foregrip", (13.3, 3.5, 7), (16, 7.3, 9), "wood_dark", "wood"),
        b("seeker_mount_back", (7.5, 13.5, 7), (9, 14.5, 9), "metal_dark"),
        b("seeker_mount_front", (14, 13.5, 7), (15.5, 14.5, 9), "metal_dark"),
        b("seeker_housing", (7, 14.5, 6.4), (16, 17, 9.6), "receiver", "metal_mid"),
        b("seeker_top", (7.5, 17, 6.7), (15.5, 17.4, 9.3), "metal_light"),
        b("seeker_eye_cup", (5.8, 14.8, 6.8), (7, 16.7, 9.2), "barrel"),
        b("seeker_rear_glass", (5.7, 15.2, 7.2), (5.8, 16.3, 8.8), "metal_light"),
        b("seeker_front_glass", (16, 15, 7), (16.1, 16.5, 9), "metal_light"),
        b("seeker_front_hood_top", (15.8, 16.5, 6.5), (17, 17.1, 9.5), "metal_dark"),
        b("seeker_front_hood_bottom", (15.8, 14.4, 6.5), (17, 15, 9.5), "metal_dark"),
        b("seeker_front_hood_left", (15.8, 15, 6.5), (17, 16.5, 7), "metal_dark"),
        b("seeker_front_hood_right", (15.8, 15, 9), (17, 16.5, 9.5), "metal_dark"),
        b("seeker_dial", (10, 15, 9.6), (11.5, 16.5, 10.1), "brass"),
        b("seeker_switch", (12.5, 15, 9.6), (14, 15.6, 10), "barrel"),
        b("rear_latch", (-3, 11, 10.5), (0, 12, 11), "metal_light"),
    ]
    # Four walls around each opening expose a recessed dark bore, not a painted cap.
    for label, x0, x1 in [
        ("muzzle", 27, 30),
        ("breech", -12, -10),
        ("rear_band", -5, -3.5),
        ("front_band", 20.5, 22),
    ]:
        pieces.extend(
            [
                b(
                    label + "_top",
                    (x0, 13, 5.2),
                    (x1, 14, 10.8),
                    "metal_mid",
                    "metal_light",
                ),
                b(label + "_bottom", (x0, 8, 5.2), (x1, 9, 10.8), "metal_dark"),
                b(label + "_left", (x0, 9, 5.2), (x1, 13, 6.2), "metal_mid"),
                b(label + "_right", (x0, 9, 9.8), (x1, 13, 10.8), "metal_mid"),
            ]
        )
    pieces += [
        b("muzzle_bore", (26.9, 9, 6.2), (27.01, 13, 9.8), "barrel"),
        b("breech_bore", (-10.01, 9, 6.2), (-9.9, 13, 9.8), "barrel"),
    ]
    model = _model(pieces)
    # Retained after shader photographs: both fists meet the grips, the muzzle
    # clears the hands, the scope clears the reticle, and the icon fits its slot.
    model["display"] = {
        "firstperson_righthand": {
            "rotation": [0, 92, 0],
            "translation": [1, 0.5, -3],
            "scale": [0.5, 0.5, 0.5],
        },
        "thirdperson_righthand": {
            "rotation": [0, 90, 0],
            "translation": [0, 1.5, 1],
            "scale": [0.55, 0.55, 0.55],
        },
        "gui": {
            "rotation": [0, 0, 0],
            "translation": [-0.4, 0, 0],
            "scale": [0.36, 0.36, 0.36],
        },
        "ground": {
            "rotation": [0, 0, 0],
            "translation": [0, 2, 0],
            "scale": [0.3, 0.3, 0.3],
        },
        "fixed": {
            "rotation": [0, 0, 0],
            "translation": [-0.4, 0, 0],
            "scale": [0.36, 0.36, 0.36],
        },
    }
    return model


