def _png(path: Path, rows: tuple[tuple[Pixel, ...], ...]) -> None:
    raw = b"".join(b"\0" + b"".join(bytes(p) for p in row) for row in rows)

    def chunk(kind: bytes, data: bytes) -> bytes:
        return (
            struct.pack(">I", len(data))
            + kind
            + data
            + struct.pack(">I", zlib.crc32(kind + data) & 0xFFFFFFFF)
        )

    path.write_bytes(
        b"\x89PNG\r\n\x1a\n"
        + chunk(b"IHDR", struct.pack(">IIBBBBB", 16, 16, 8, 6, 0, 0, 0))
        + chunk(b"IDAT", zlib.compress(raw, 9))
        + chunk(b"IEND", b"")
    )


def generate(want: set[str]) -> None:
    """requires: repository resource directories exist; want names textures/model.

    effects: regenerates only launcher models and part icons. throws: OSError on I/O failure.
    """
    if "model" in want:
        models = {"rocket_launcher": _launcher(), "rocket_projectile": _rocket()}
        for name in ICONS:
            models[name] = {
                "credit": CREDIT,
                "parent": "minecraft:item/generated",
                "textures": {"layer0": f"rangedweaponsmod:item/{name}"},
            }
        for name, model in models.items():
            (ASSETS / f"models/item/{name}.json").write_text(
                json.dumps(model, indent=2) + "\n"
            )
    if "textures" in want:
        for name, rows in ICONS.items():
            _png(
                ASSETS / f"textures/item/{name}.png",
                bevel([[PALETTE[c] for c in row] for row in rows]),
            )


if __name__ == "__main__":
    generate({"textures", "model"})
